import{z as s,x as o,o as A,c as D,q as r,j as t,D as e,d as B,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"优先级与公平性","description":"","frontmatter":{"title":"优先级与公平性","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-priority-fairness.md","filePath":"llm/sch-priority-fairness.md","lastUpdated":1791413859000}'),d={name:"llm/sch-priority-fairness.md"};function F(p,E,C,m,h,f){const l=o("Mermaid");return A(),D("div",null,[E[2]||(E[2]=r('<h1 id="优先级与公平性" tabindex="-1">优先级与公平性 <a class="header-anchor" href="#优先级与公平性" aria-label="Permalink to &quot;优先级与公平性&quot;">​</a></h1><div class="epigraph"><p>FCFS 公平的是到达顺序，产出的是不公平的服务量；优先级是合同的排序，公平衡量的是每类流量拿到的那一份。</p><footer>—— 据 Ghodsi et al., NSDI 2011（DRF）与 Jain 公平指数（1984）整理</footer></div><p><a href="/llm/sch-continuous-batching-deep">上一课</a>把每一步的预算与次序钉住，但预算默认所有请求无差别。真实流量有类别：付费交互、免费额度、内部批处理；FCFS 让短请求陪葬长 decode，纯优先级让低级类饿死。本课钉类别怎么定义、权重怎么服务、两种资源（步时延名额与 KV 字节）上的公平怎么量。抢占的单机机制主干已有（<a href="/llm/preemption-fairness">抢占与公平性</a>），本课把公平写成可验收的调度策略，不重讲换出与重算。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公平的第一陷阱是「一维化」。<span class="marginnote">术语翻译：FCFS（先来先服务）就是排队买票——谁先到谁先办，对「到达顺序」公平。但一条长请求排在队头时，后面一串短请求全都干等：顺序上公平了，服务量上反而不公平，这就是「公平的第一陷阱」。</span>把公平定义为等待时间相等，产出的是工作量不等：短请求与 8k 上下文的 agent 拿到同样的等待，等于短请求补贴长请求。把公平定义为条数份额相等，在异质请求下同样失真：一条长 decode 占用的 KV 字节是短补全的百倍，「条数」对齐时字节严重不对齐。<span class="marginnote">数字实例：一条 8k 上下文的请求与一条 200 token 的短补全，KV 字节差约 40 倍。若按「条数相等」分配，两个类条数对齐了，字节上却差着几十倍——公平必须定在资源占用上，而不是请求条数上。</span>而这里确实是两种货币：每步的算力名额与 KV 池字节，不同负载下瓶颈位不同。第二个陷阱是纯优先级：只要高级别流量持续到达，低级类可以无限饥饿——这在产品上通常不可接受，哪怕低级类只是内部工具。</p><h3 id="类别、权重与保底" tabindex="-1">类别、权重与保底 <a class="header-anchor" href="#类别、权重与保底" aria-label="Permalink to &quot;类别、权重与保底&quot;">​</a></h3><p>工程解是三层结构：<strong>类别</strong>由合同定义（下一课的 SLO 分层）；类内 FCFS；类间加权服务。迭代级执行：每一步按权重在各类间分配 token 预算与准入名额，权重是「份额」不是「禁止」——低权类拿到小份额但必有进展。防饿死用老化：等待时长折算成权重增益，饿到阈值强制插队。<span class="marginnote">直觉类比：老化就像餐厅等位叫号——普通号码每等一分钟涨一点优先级，饿得太久的号自动升级成「金号」，下次有空桌必须先请它。这保证「优先订座的 VIP」再怎么源源不断，散客也不会永远吃不上饭。</span>KV 是第二种货币，用租约管理：单请求的 KV 占用超过其类份额（长上下文、并行采样）时，优先成为抢占候选——「占用多者先让」而不是「后来者永远让」（<a href="/llm/preemption-fairness">抢占与公平性</a>）。</p>',7)),(A(),t(n,null,{default:e(()=>[i(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%88%B0%E8%BE%BE%EF%BC%9A%E6%89%93%E7%B1%BB%E5%88%AB%E6%A0%87%22%5D%20--%3E%20QI%5B%22%E4%BA%A4%E4%BA%92%E7%B1%BB%E9%98%9F%E5%88%97%22%5D%0A%20%20REQ%20--%3E%20QA%5B%22Agent%20%E7%B1%BB%E9%98%9F%E5%88%97%22%5D%0A%20%20REQ%20--%3E%20QB%5B%22%E6%89%B9%E5%A4%84%E7%90%86%E7%B1%BB%E9%98%9F%E5%88%97%22%5D%0A%20%20QI%20--%3E%20WFQ%5B%22%E5%8A%A0%E6%9D%83%E6%9C%8D%E5%8A%A1%EF%BC%9A%E6%8C%89%E4%BB%BD%E9%A2%9D%E5%88%86%E6%AD%A5%E9%A2%84%E7%AE%97%22%5D%0A%20%20QA%20--%3E%20WFQ%0A%20%20QB%20--%3E%20WFQ%0A%20%20WFQ%20--%3E%20AGE%7B%22%E9%A5%A5%E9%A5%BF%E8%B6%8A%E7%BA%BF%22%7D%0A%20%20AGE%20--%3E%7C%E6%98%AF%7C%20BOOST%5B%22%E8%80%81%E5%8C%96%E6%8F%90%E6%9D%83%EF%BC%8C%E5%BC%BA%E5%88%B6%E6%8F%92%E9%98%9F%22%5D%0A%20%20AGE%20--%3E%7C%E5%90%A6%7C%20ENG%5B%22%E5%BC%95%E6%93%8E%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%22%5D%0A%20%20BOOST%20--%3E%20ENG%0A%20%20ENG%20--%3E%20MEAS%5B%22%E4%B8%89%E5%88%97%E9%AA%8C%E6%94%B6%EF%BC%9A%E7%9F%AD%20TTFT%20P95%20%2F%20%E9%95%BF%20E2E%20P95%20%2F%20%E6%9C%80%E9%95%BF%E9%A5%A5%E9%A5%BF%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"方法",tabindex:"-1"},[B("方法 "),a("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[4]||(E[4]=a("p",null,[B("本课的方法是"),a("strong",null,"三层结构加两个量化工具"),B("：类别由合同定义、类内 FCFS、类间加权服务，防饿死用老化提权；两种货币（步时延名额与 KV 字节）分开记账。量化工具取 DRF 的主导资源思想处理多维公平——各自主导份额尽量相等——Jain 指数做监测，只做体检不做优化目标。验收定成三列：短请求 TTFT 分位、长请求端到端分位、最长饥饿时长；公平与效率的前沿靠实测，份额粒度是定价。")],-1)),E[5]||(E[5]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[6]||(E[6]=a("p",null,"多维公平的量化工具是主导资源思想（DRF，Ghodsi et al., NSDI 2011）：把每类在两种资源上的份额各自归一化，取其最大者作为该类的「主导份额」，公平方案让各主导份额尽量相等——没有谁在两个维度上同时被压。DRF 怎么算，代入一组数：",-1)),(A(),t(n,null,{default:e(()=>[i(l,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%B1%BB%20A%EF%BC%9A%E6%AD%A5%E9%A2%84%E7%AE%97%E4%BB%BD%E9%A2%9D%200.6%EF%BC%8CKV%20%E4%BB%BD%E9%A2%9D%200.3%22%5D%20--%3E%20DA%5B%22%E4%B8%BB%E5%AF%BC%E4%BB%BD%E9%A2%9D%20%3D%20%E6%9C%80%E5%A4%A7%E8%80%85%200.6%22%5D%0A%20%20B%5B%22%E7%B1%BB%20B%EF%BC%9A%E6%AD%A5%E9%A2%84%E7%AE%97%E4%BB%BD%E9%A2%9D%200.4%EF%BC%8CKV%20%E4%BB%BD%E9%A2%9D%200.7%22%5D%20--%3E%20DB%5B%22%E4%B8%BB%E5%AF%BC%E4%BB%BD%E9%A2%9D%20%3D%20%E6%9C%80%E5%A4%A7%E8%80%85%200.7%22%5D%0A%20%20DA%20--%3E%20CMP%7B%22%E4%B8%A4%E4%B8%AA%E4%B8%BB%E5%AF%BC%E4%BB%BD%E9%A2%9D%E7%9B%B8%E7%AD%89%E5%90%97%EF%BC%9F%22%7D%0A%20%20DB%20--%3E%20CMP%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E7%AD%89%22%7C%20ADJ%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E5%90%91%20A%20%E5%80%BE%E6%96%9C%EF%BC%8C%E5%8E%8B%E4%BD%8E%20B%20%E7%9A%84%20KV%20%E5%8D%A0%E6%AF%94%22%5D%0A%20%20ADJ%20--%3E%20A%0A%20%20CMP%20--%3E%7C%22%E6%8E%A5%E8%BF%91%22%7C%20FAIR%5B%22%E5%A4%9A%E7%BB%B4%E5%85%AC%E5%B9%B3%EF%BC%9A%E6%B2%A1%E6%9C%89%E8%B0%81%E8%A2%AB%E5%90%8C%E6%97%B6%E5%8E%8B%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=r('<p>监测用 Jain 指数 \\(J=(\\sum x_i)^2/(n\\sum x_i^2)\\)：把各类实际服务量代入，\\(J=1\\) 完全均等，越偏离越集中。指数只做体检不做目标：把 \\(J\\) 写进优化目标会鼓励把高级流量拆碎凑均等。公平与效率是前沿：加权轮转打乱批的紧凑度，goodput 掉多少必须实测；份额切得越细，损失越大。优先级反转发生在一次前向内部：高级请求与低级的 prefill 块同批前进，类间权重管不到步内——唯一救法是把本步 token 预算也按类切，上一课的预算机制在此获得策略含义。</p><p><span class="marginnote">Jain 指数的小算例：两租户实际拿到 0.8 与 0.2 的 token 份额，\\(J=1/(2\\times(0.64+0.04))\\approx 0.74\\)；拿到 0.6 与 0.4 时 \\(J\\approx 0.96\\)。指数对极端偏斜敏感、对温和偏斜宽容，正好用来盯饿死，而不是盯绝对均衡。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>软权重挡不住对抗：恶意租户可以靠多开请求放大自身份额，合同级的硬边界要配额与切片（<a href="/llm/multi-tenant-gpu">多租户隔离</a> 的三层框架，本课程末课深化）。公平也不等于满足合同：每类「拿到了等比例服务」与「分位达标」是两回事，后者是下一课的主题。机群层面多作业的 gang 与多资源公平另有专门机制（<a href="/llm/cluster-fair-scheduling">机群公平调度</a>），本课停在单引擎之内。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FCFS 公平的是到达序；公平必须定义在工作量与资源占用的份额上。</li><li>类间加权服务、类内 FCFS、老化保底，是迭代级调度的策略层。</li><li>两种货币（步时延名额与 KV 字节）分开记账，DRF 思想处理多维。</li><li>公平验收看三列：短请求 TTFT P95、长请求 E2E P95、最长饥饿时长。</li><li>步内反转用按类切预算解决；公平与效率是前沿，份额粒度是定价。</li><li>出处：Ghodsi et al., NSDI 2011（DRF）；Jain 公平指数（1984）；迭代级钩子见 Yu et al., OSDI 2022。</li></ul>',6))])}const T=s(d,[["render",F]]);export{c as __pageData,T as default};
